// ca — Català (catalão).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// POR QUE ENTROU: é a língua oficial de ANDORRA, e Andorra era um dos cinco membros da ONU que nenhuma
// língua do Syden alcançava. De quebra, alcança uns dez milhões de pessoas na Catalunha, em Valência e
// nas Baleares, que leem espanhol mas preferem a própria língua.
//
// TOM: **tu**. O guia da Softcatalà, que traduz boa parte do software livre em catalão, prefere o *vós*
// nas mensagens; o Syden fica com o tu pela regra de toda a casa (ver CLAUDE.md, "Os idiomas tratam por
// você"), que é também o que os apps de conversa em catalão usam.
//
// GÊNERO: como no português, mora no adjetivo e no particípio sobre quem lê — benvingut / benvinguda,
// convidat / convidada, silenciat / silenciada. Saída: a frase vira verbo ou coisa ("Et donem la
// benvinguda", "Tens una invitació", "Tens el micròfon silenciat").
//
// APÓSTROFO: o catalão apostrofa o tempo todo (l’enquesta, d’àudio). Vai sempre o TIPOGRÁFICO (’), que é
// a grafia correta e poupa o \' que já engoliu pares de outro dicionário.
//
// NÚMEROS: `Intl.NumberFormat('ca')` devolve `1.234.567` — latinos, com ponto.
//
// O DETECTOR DO TESTE DE IDIOMAS: o catalão escreve "comunitat", "missatge", "idea" — perto demais do
// português para o detector por palavras. Vai o das chaves.
//
// VOCABULÁRIO, decidido uma vez: comunidade = comunitat, canal = canal, sala de voz = sala de veu,
// chamada = trucada, conversa = conversa, mensagem = missatge, senha = contrasenya, lixeira = paperera,
// tópico = fil, conta = compte, administrador = administrador, dono = propietari, cargo = rol, convite =
// invitació, perfil = perfil, transmissão = transmissió, tela = pantalla, membro = membre, pacote =
// paquet, enquete = enquesta, denúncia = denúncia, vila = poble, guarda-roupa = armari, cutucada = toc,
// recado (da tela de boas-vindas e do aviso) = avís.
//
// SOM E VOZ SÃO DUAS PALAVRAS: veu é a voz, so é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = segell (o da comunidade), insígnia = insígnia (a da pessoa).

