  'Seu chute': 'El teu intent',
  'Chutes: {n}': 'Intents: {n}',
  'Monstros de fantasia': 'Monstres de fantasia',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Surt un monstre secret, i cadascú en prova d’altres de la llista. Cada intent mostra el que coincideix amb el secret: tipus, mida, nivell, alineament i com es desplaça. Qui l’encerta amb menys intents guanya més punts.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'Surt una figura secreta de la mitologia, i cadascú en prova d’altres. Cada intent mostra el que coincideix amb la secreta: la mitologia, el tipus, la forma i el que governa. Qui l’encerta amb menys intents guanya més punts.',
  'Países': 'Països',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'Surt un país secret, i cadascú en prova d’altres. Cada intent mostra la distància i la direcció fins al secret, la regió, la subregió i la població. Qui l’encerta amb menys intents guanya més punts.',
  'Apagar conversa': 'Esborra la conversa',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'La conversa surt de la teva llista i els missatges desapareixen només per a tu. Les altres persones continuen veient-ho tot, i un missatge nou torna a portar la conversa.',
