  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'La fusta s\'esquerda quan algú s\'hi queda a sobre. Continua movent-te i empeny els altres a l\'aigua!',
  'A torre do celeiro': 'La torre del graner',
