  'A turma caiu.': 'La colla ha caigut.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Tota la colla contra el talp rei, que surt dels caus en tres fases. Esquiva les marques del terra, agafa els terrossos blavosos i torna\'ls-hi. Guanya la colla, o ningú.',
  'Abóboras ladeira abaixo': 'Carbasses costa avall',
  'Acerte os corvos que passarem. No coelhinho, não!': 'Encerta els corbs que passin. El conillet no!',
