  'Afofa a terra': 'Estova la terra',
  'Água e sol': 'Aigua i sol',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Alterna ← i → amb ritme. Amb massa pressa, s\'acaba l\'alè.',
  'Ao calendário': 'Al calendari',
  'Ao guarda-roupa': 'A l\'armari',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Prem la fletxa que aparegui per estirar la corda. Si t\'equivoques, et bloqueges!',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Prem per frenar la roda. Sempre llisca una mica abans de parar.',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Prem sense parar per nedar. Quan vingui un tronc, capbussa\'t!',
