  'Barraca de tiro': 'Barraca de tir',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Pica les erugues que surtin dels caus. El conillet no!',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Pica quan surti la flor igual a la del requadre. Amb la figura equivocada, quedes fora.',
  'Batata': 'Patata',
