  'Bomba de semente pronta': 'Bomba de llavors a punt',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Bomba quan l\'anell s\'encengui. Fora de ritme, l\'aire s\'escapa.',
  'Brasas da fogueira': 'Brases de la foguera',
  'Cabo de guerra': 'Estirar la corda',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Cadascú rema per un costat: la remada empeny el rai cap a l\'altre. Junts, avança. Agafeu les pastanagues!',
  'Caiu! Agora é torcer de longe.': 'Fora de combat! Ara toca animar de lluny.',
  'Canteiro que encolhe': 'Parcel·la que s\'encongeix',
