  'Chão que desmorona': 'Terra que s\'esfondra',
  'Chuva de cenouras': 'Pluja de pastanagues',
  'Cinco': 'Cinc',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Conills en avionetes sobre l\'hort, disparant pèsols i una pastanaga teledirigida cada vegada. Dos impactes s\'aguanten; el tercer et fa caure. Guanya l\'últim que queda a l\'aire.',
  'Colheita em dupla': 'Collita en parella',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Menja\'t el pastís amb la teva parella, alternant ◀ i ▶. Guanya qui acabi primer!',
  'Come as folhas': 'Es menja les fulles',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Curses de barquetes al llac, al rierol i al manglar. L\'aigua llisca: deixa l\'accelerador abans del revolt, compte amb la vora i aprofita el corrent i les anelles. En individual, contra rellotge i els fantasmes dels amics.',
  'Corrida de cavalinho': 'Cursa de cavallets',
  'Dano da turma: {n}': 'Dany de la colla: {n}',
  'De galho em galho': 'De branca en branca',
  'De que cor é a folha da cenoura?': 'De quin color és la fulla de la pastanaga?',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Baixa agafant les pastanagues. Fuig de les pedres!',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Descobreix qui s\'amaga. Una sola oportunitat: com més aviat, més val.',
  'Destampe os potes': 'Destapa els pots',
  'Desvie das brasas. São só três corações!': 'Esquiva les brases. Només hi ha tres cors!',
  'Dez': 'Deu',
  'Do que uma planta precisa para crescer?': 'Què necessita una planta per créixer?',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'Dos impactes s\'aguanten; el tercer et fa caure. Un gir tancat a prop de la tanca protegeix un instant.',
  'Duas': 'Dues',
  'Duelo de aviõezinhos': 'Duel d\'avionetes de paper',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'En parella: qui és a la branca deixa caure les maduixes madures, i qui és a baix les recull amb la cistella.',
  'Em que dia é o aniversário do Syden?': 'Quin dia és l\'aniversari del Syden?',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Empeny els altres fora de la parcel·la. La vora que parpelleja caurà!',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Arracona la gallina. Cansada, va més lenta.',
