  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Esquiva les marques del terra. Passa per sobre d\'un terròs blavós per agafar-lo i llança\'l al talp; la bomba de llavors és una per fase.',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Gira cada tapa cap al costat de la fletxa, de pressa. El costat equivocat la torna a estrènyer.',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Recorda l\'ordre del ball. Al final, digues qui va ballar a la làmpada marcada.',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Recorda on va cada pot i torna\'ls tots al seu lloc.',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Des de dalt rodolen carbasses; qui puja canvia de carril per esquivar-les!',
  'Lagarta': 'Eruga',
