  'Lesma': 'Llimac',
  'Leve a nuvem até o canteiro com sede.': 'Porta el núvol fins a la parcel·la assedegada.',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Porta les tres fustes fins al pont. Compte amb les pedres que s\'enfonsen!',
