  'Na cama': 'Al llit',
  'Na Corrida dos coelhos, o kart do mascote parece o quê?': 'A la Cursa de conills, a què s\'assembla el kart de la mascota?',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'Al teu torn, gira una carta o desa les pastanagues. La guineu s\'ho emporta tot!',
  'Nenhum amigo subiu esta torre ainda.': 'Cap amic no ha pujat aquesta torre encara.',
