  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Atura cada franja amb el retrat al seu lloc, de dalt a baix.',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Atura els tres rodets a la mateixa figura. Cada trio val un punt.',
