  'Sem vidas: agora é torcer pela turma.': 'Sense vides: ara toca animar la colla.',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Segueix els bitxos de cau en cau. Al final, assenyala on és el del globus.',
  'Silo': 'Sitja',
  'Solte o cipó quando ele estiver na faixa clara.': 'Deixa anar la liana quan sigui a la franja clara.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Deixa anar quan el nap apunti al camp. Com més ràpid giri, més lluny arriba.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Puja fins al penell. Les caigudes i els corbs et tornen a l\'últim pis.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Puja el graner per fustes, bales de palla i bigues que es mouen fins al penell de dalt de tot, esquivant les eines que cauen i els corbs. En individual, contra rellotge i els fantasmes dels amics.',
