  '{n} voltas': '{n} voltes',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'L\'energia és la vida i el turbo: xocar amb la vora la gasta, la franja rosa la recarrega.',
  'A nave explodiu: a energia acabou.': 'La nau ha explotat: s\'ha acabat l\'energia.',
  'Posição: {posicao} de {total}': 'Posició: {posicao} de {total}',
  'Escolher a pista': 'Triar la pista',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Cursa de naus-pastanaga en una pista suspesa, molt més ràpida que el kart. L\'energia és la vida i el turbo: xocar amb la vora la gasta, la franja rosa la recarrega, i sortir de la pista és caure. En Individual, contra el rellotge i els fantasmes dels amics.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Els karts en una arena tancada, cada un amb tres globus. Agafa les caixes i fes servir els objectes per rebentar els globus dels altres: qui es queda sense globus queda fora, i guanya qui sobrevisqui.',
  'Esquadrilha da toca': 'Esquadreta del cau',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Avionets de pastanaga contra la plaga de l\'hort: esquiva les llavors, agafa els reforços i abat l\'espantaocells mecànic al final. La colla vola les mateixes onades, i l\'esquadreta suma els punts.',
  'O espantalho caiu!': 'L\'espantaocells ha caigut!',
  'A praga venceu desta vez.': 'La plaga ha guanyat aquesta vegada.',
