  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Vuit forats en 3D, amb rampes, castell i molí, tothom juga el mateix alhora. Arrossega per apuntar i donar la força, i deixa anar. Guanya qui sumi menys cops.',
  'Ver o buraco de cima': 'Veure el forat des de dalt',
  'Fora da pista! Mais uma tacada.': 'Fora de la pista! Un cop més.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Arrossega cap al costat per apuntar i cap avall per a la força, i deixa anar. Amb el teclat: les fletxes apunten, i mantenir l\'Espai dona la força.',
  'Futebol dos coelhos': 'Futbol dels conills',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Futbol de camp petit, vist des de dalt. Toca la pilota per conduir-la, mantén l\'Espai per xutar més fort i passa amb X. A la sala, els equips es completen amb robots.',
