  'Caça às pragas da horta': 'Caça de plagues a l\'hort',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Corbs i llagostes ataquen l\'hort. Apunta i fes clic per encertar-los abans que fugin: la munició és comptada, i cada onada arriba més ràpida. Guanya qui faci més punts.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Apunta i fes clic a les plagues abans que fugin. Cada tret gasta una pastanaga.',
