  'Tacadas: {n}': 'Cops: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Estira la bola enrere i deixa-la anar. Amb el teclat: les fletxes apunten, i mantenir l\'Espai dona la força.',
  'Na água! Mais uma tacada.': 'A l\'aigua! Un cop més.',
  'No buraco!': 'Al forat!',
  'Acabaram as tacadas.': 'S\'han acabat els cops.',
  'Para a esquerda': 'Cap a l\'esquerra',
  'Para a direita': 'Cap a la dreta',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Fletxes per córrer, Espai per saltar (mantén-lo per anar més amunt).',
  'Nenhum amigo jogou esta fase ainda.': 'Cap amic no ha jugat encara aquest nivell.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Pluja a l\'hort: tothom guanya {n} pastanagues.',
  '{nome} achou {n} cenouras escondidas.': '{nome} ha trobat {n} pastanagues amagades.',
  '{nome} trocou de lugar com {outro}.': '{nome} ha canviat de lloc amb {outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Faltava gent: la partida ha acabat abans d\'hora, sense trofeus.',
  'Saiu antes do fim': 'Ha marxat abans del final',
  'Jogar o dado': 'Tirar el dau',
  '{nome} comprou a cenoura dourada!': '{nome} ha comprat la pastanaga daurada!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Comprar la pastanaga daurada per {preco} pastanagues?',
  'Comprar': 'Comprar',
  '{nome} chegou à cenoura dourada.': '{nome} ha arribat a la pastanaga daurada.',
  'Quantas rodadas?': 'Quantes rondes?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Els conills defensen l\'hort de guineus, corbs i un teixó. Avanceu plegats, piqueu en combo i cuideu-vos entre tots: d\'1 a 4 persones.',
  'Pulo do coelho': 'Salt del conill',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Una cursa de plataformes: córrer, saltar i no caure. En solitari, contra rellotge i els fantasmes dels amics; amb la colla, en directe, en un nivell o en tots tres.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Intercanvia dues verdures veïnes per ajuntar-ne tres o més d\'iguals. La pila puja sense parar: no deixis que arribi a dalt. Amb la colla, les cadenes i els combos envien caixes als altres.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Sis forats de minigolf, tothom jugant el mateix alhora. Estira la bola enrere i deixa-la anar per fer el cop. Guanya qui sumi menys cops.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Per torns, es tira el dau i s\'avança per l\'hort. Recull pastanagues per comprar la pastanaga daurada, i després de cada ronda la colla juga un microjoc. Guanya qui tingui més pastanagues daurades.',
