  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Recorre les capitals del Brasil, compra ciutats i cobra lloguer a qui s’hi aturi. Amb una regió sencera, pots construir edificis. Intercanvia, puja a les subhastes i no et quedis sense diners.',
