  'Damas': 'Dames',
  'Batalha naval': 'Enfonsar la flota',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'El dòmino de sempre, de 2 a 4 persones (amb 4, en parelles). Encaixa les fitxes pels extrems, i qui dòmini primer s\'emporta els punts de les mans dels altres.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'El truco brasiler, amb la girada i les manilles, d\'a 2 o en parelles d\'a 4. Canta truco, puja a sis, nou i dotze, o retira\'t. Guanya qui arribi a 12 punts.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Les dames brasileres: menjar és obligatori, endavant i endarrere, i la dama recorre la diagonal sencera. La sala mira.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Cadascú amaga la seva flota i dispara al mar de l\'altre. Si l\'encertes, tornes a disparar. Guanya qui enfonsi tota la flota primer. La sala mira.',
