  Xadrez: 'Escacs',
  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': "Una partida d'escacs sencera, amb totes les regles. Qui obre juga amb blanques. La sala mira.",
  'Xeque!': 'Escac!',
  Dama: 'Dama',
