  Bispo: 'Alfil',
  'Cozinha da toca': 'La cuina del cau',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': "Agafa els ingredients de les caixes, talla'ls al tauler, cuina'ls al fogó i al forn sense cremar-los, munta el plat i lliura'l a la finestra. Tothom rep les mateixes comandes: guanya qui lliura més plats en 3 minuts.",
  'Pegar ou largar': 'Agafar o deixar',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': "Aquest joc necessita gràfics 3D, que no s'han obert en aquest aparell.",
  'Este prato não é o pedido.': 'Aquest plat no és la comanda.',
