  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Registres limitats de Docker, SSH, logind i nucli de les tres arrencades més recents. Poden contenir adreces IP.",
  "Atualizar diagnóstico": "Actualitza el diagnòstic",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Encara no hi ha captura. Es recollirà la pròxima vegada que s’obri la caixa forta.",
  "Coletado em {data}": "Recollit el {data}",
  "Medido pela {nome}": "Mesurat per {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Els mateixos números del tauler del proveïdor. Inclou el disc, que el servidor no mesura sol.",
  "Ações no servidor": "Accions al servidor",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "L’historial d’Hetzner: engegar, apagar i reiniciar, des del tauler o l’API. Una caiguda sense cap acció aquí no s’ha ordenat per aquestes vies.",
