  'Desfocado': "Difuminar",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Difumina, esborra o substitueix el que es veu darrere teu. La imatge de la càmera no surt del teu ordinador per fer-ho.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Nativa",
  'Resolução': "Resolució",
  'Quadros por segundo': "Fotogrames per segon",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Per quan l'elecció automàtica s'equivoca: la resolució i els fotogrames són els que triïs, de principi a fi de la transmissió.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Els efectes de veu i de càmera que es fan al teu ordinador, sense enviar res a cap servidor.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Comando Pastanaga",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Corre i dispara amb la colla: el llançapastanagues apunta en vuit direccions, la granada obre camí i qui allibera els conillets engabiats guanya reforç. El drac espera al final: d'1 a 4 persones.",
  'Andar e mirar': "Camina i apunta",
  'Granada': "Granada",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "La masmorra del cau",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Travesseu junts el cau del rei bolet: sales plenes de bestioles, un cofre amb la pastanaga que va i torna, botons que en demanen dos alhora i la porta tancada amb clau. D’1 a 4 persones.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ring del cau",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Boxa de reflexos contra tres rivals de l'ordinador. Llegeix l'avís de cada cop, esquiva o defensa't i pica a l'obertura. Picar quan el guant brilla omple l'estrella del cop fort.",
  'Esquivar': "Esquivar",
  'Abaixar e defender': "Ajupir-se i defensar",
  'Socar': "Picar",
  'Soco forte': "Cop fort",
  'Aperte os socos para levantar!': "Prem els cops per aixecar-te!",
  'Lutas vencidas: {n}': "Combats guanyats: {n}",
  'Nocaute!': "K.O.!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Ruta Estel·lar",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Conills en naus per la superfície d'un planeta i per l'espai: dispara, mantén el tret per fixar el blanc, gira per desviar els trets i tria el camí a la bifurcació. La colla vola la mateixa ruta, i el cap espera al final.",
  'Pirueta': "Pirueta",
  'Segure para travar a mira': "Mantén per fixar el blanc",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Pinball de l’hort",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Una taula de pinball a l’hort: aguanta la molla, fes rebotar la bola a les cols i tomba les tres pastanagues per encendre el cau del conill, que deixa anar una bola més. Tres boles, i sacsejar massa bloqueja la taula.",
  'Palhetas': "Paletes",
