  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Un RPG per torns curt: cadascú controla un heroi del grup. Trieu junts, combineu atacs i venceu el drac del castell.",
