  "Gênero": "Gènere",
  "Levadiça": "Llevadís",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Encara no hi ha cap conversa. Toca algú a la llista de persones de la comunitat i tria \"Enviar un missatge\".",
  "Varia": "Varia",
  "Vitória de {nomes}": "Victòria de {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Heu enderrocat els dos centres del poble de l'altre equip.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "La ciutat que ningú compra va a subhasta. Hipotecar una ciutat dona diners, però no cobra lloguer.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "La pista il·lumina la peça que es mou. El problema amb pista no puntua; a la cursa, treu 10 segons.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "La manilla és el valor següent al de la girada i guanya a totes. Entre elles: oros, espases, copes i bastos, el zap.",
  "A última nave de cada volta sai.": "L'última nau de cada volta queda fora.",
  "Abaixar": "Ajupir-se",
  "Acertos em sequência: {n}": "Encerts seguits: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Avança amb el dau i compra la capital on caiguis. Qui cau a la ciutat d'un altre paga lloguer.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Cada fila, columna i bloc de 3 × 3 té els números de l'1 al 9, sense repetir.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Cadascú rep 3 cartes. S'emporta la mà qui guanyi 2 de les 3 rondes.",
  "Campeonato": "Campionat",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Amb 11 punts, la parella veu les cartes i decideix si juga la mà d'onze. Guanya qui arribi a 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Amb la regió sencera, construeix fins a 4 edificis: el lloguer puja amb cadascun.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Amb estrelles, el cop fort (★) les gasta totes de cop i fa més mal.",
  "Dica": "Pista",
  "Dica: este problema não pontua": "Pista: aquest problema no puntua",
  "Dica: tira 10 segundos": "Pista: treu 10 segons",
  "Eliminação": "Eliminació",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Arrambla una fitxa a un extrem de la taula amb el mateix número.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Tria la casella i després el número. El llapis anota només per a tu.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Esquiva el cop i pica just després: és el contraatac, i val una estrella.",
  "Fora da corrida na volta {n}.": "Fora de la cursa a la volta {n}.",
  "Força das cartas": "Força de les cartes",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Guanya el patrimoni més gran al final de les rondes, o qui quedi.",
  "Iniciante": "Principiant",
  "Mestre": "Mestre",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "A Ratxa, cada encert porta un problema més difícil, i el primer error l'acaba.",
  "O número pequeno no botão diz quantos ainda faltam.": "El número petit del botó diu quants en falten encara.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Els cinc circuits seguits contra l'ordinador, amb punts.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Canta truco i la mà val 3. Qui respon accepta, es retira o puja a 6, 9 o 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Qui domina es queda sense fitxes i s'emporta els punts de les mans dels altres. Si es tanca, se'ls emporta qui té menys punts a la mà.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Sense fitxa que serveixi, roba. Sense res per robar, passa el torn.",
  "Sequência": "Ratxa",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Pica quan el guant brilli: el cop s'atura i guanyes una estrella.",
