  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Amb la captura, encerclar dues pedres de l'altre entre dues teves les treu totes dues; cinc captures també guanyen.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Amb la regla 3-3, les negres no poden fer dos tres oberts alhora.",
