  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Surt un animal secret, i cadascú en prova d’altres. Cada intent mostra què coincideix amb el secret: la classe, la dieta, on viu i el pes. Qui l’endevina amb menys intents guanya més punts.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Surt un dinosaure secret, i cadascú en prova d’altres. Cada intent mostra què coincideix amb el secret: el període, la dieta, el grup, la longitud i on es va trobar. Qui l’endevina amb menys intents guanya més punts.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Surt un element químic secret, i cadascú en prova d’altres. Cada intent mostra què coincideix amb el secret: la família, l’estat físic, el període, el grup i el nombre atòmic. Qui l’endevina amb menys intents guanya més punts.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Surt un estat secret del Brasil, i cadascú en prova d’altres. Cada intent mostra la distància i la direcció fins al secret, la regió, la població, l’àrea, el litoral i la frontera amb un altre país. Qui l’endevina amb menys intents guanya més punts.",
